/**
 * P11 thinking-core: the clocks, models and contracts shared by every Eased thinking state
 * (Shimmer Text, Thinking Bar, Agent Orb, Step Rail, Reasoning, Tool Call Row, Agent Run).
 * Import from here; the files behind it may move.
 */
export {
  SETTLED_STEP,
  SETTLED_TOOL,
  toolStateFromPart,
  type AISDKToolPartState,
  type Step,
  type StepStatus,
  type ToolState,
} from "./types";
export { advanceSteps, summarizeSteps, updateStep, type StepSummary } from "./steps";
export { formatElapsed, useElapsed, type UseElapsedOptions } from "./use-elapsed";
export { useTokenRate, type TokenRate, type UseTokenRateOptions } from "./use-token-rate";
export { useStatusCarousel, type UseStatusCarouselOptions } from "./use-status-carousel";

/**
 * Frozen cross-lane contracts (P11). Lane 2 (Chat) and later Thinking items import these;
 * add members only with a coordinated change, because consumers switch over them exhaustively.
 */

/**
 * Where one step of a run is.
 *
 *   pending   queued, not started
 *   active    running now (one per level, usually)
 *   complete  finished successfully
 *   error     failed; the run may continue or stop
 *   skipped   not needed after all (cancelled plan steps, short-circuited checks)
 */
export type StepStatus = "pending" | "active" | "complete" | "error" | "skipped";

/**
 * Where one tool call is. A superset of the AI SDK's tool-part states, collapsed to what the
 * UI distinguishes; map AI SDK parts with `toolStateFromPart`.
 *
 *   pending            input still streaming in, or queued
 *   awaiting-approval  needs the user to approve or deny before it runs
 *   running            executing
 *   done               returned output
 *   error              threw or returned an error
 *   denied             the user declined it
 */
export type ToolState = "pending" | "awaiting-approval" | "running" | "done" | "error" | "denied";

/** States after which a step or tool will not change again. */
export const SETTLED_STEP: ReadonlySet<StepStatus> = new Set(["complete", "error", "skipped"]);
export const SETTLED_TOOL: ReadonlySet<ToolState> = new Set(["done", "error", "denied"]);

/** One step of a run: a chain-of-thought line, a plan item, an agent action. */
export type Step = {
  /** Stable id: steps are keyed by it, so re-ordering moves rows instead of re-mounting them. */
  id: string;
  label: string;
  status: StepStatus;
  /** A secondary line: a URL read, a count found, an error message. */
  detail?: string;
  /** Epoch ms when the step became active. */
  startedAt?: number;
  /** Epoch ms when it settled. */
  endedAt?: number;
  /** Nested sub-steps. */
  steps?: Step[];
};

/** The AI SDK (v5+) tool-part `state` values `toolStateFromPart` understands. */
export type AISDKToolPartState =
  | "input-streaming"
  | "input-available"
  | "approval-requested"
  | "approval-responded"
  | "output-available"
  | "output-error"
  | "output-denied";

/**
 * Maps an AI SDK tool part to a `ToolState`, so `useChat` messages drive Eased tool UI directly:
 * `toolStateFromPart(part)` where `part.type` starts with `tool-`. Unknown states read as `pending`.
 */
export function toolStateFromPart(part: { state?: string; approval?: { approved?: boolean } }): ToolState {
  switch (part.state as AISDKToolPartState | undefined) {
    case "input-available":
      return "running";
    case "approval-requested":
      return "awaiting-approval";
    case "approval-responded":
      return part.approval?.approved === false ? "denied" : "running";
    case "output-available":
      return "done";
    case "output-error":
      return "error";
    case "output-denied":
      return "denied";
    default:
      return "pending";
  }
}

import { SETTLED_STEP, type Step, type StepStatus } from "./types";

/** A run's summary, derived from its steps. Pure: call it in render. */
export type StepSummary = {
  /** Leaf and parent steps at the top level. */
  total: number;
  /** Top-level steps that have settled (complete, error or skipped). */
  settled: number;
  completed: number;
  errored: number;
  /** settled / total, 0–1: what a progress rail draws to. 0 for an empty run. */
  progress: number;
  /** The first active top-level step, or the first pending one if none is active yet. */
  current: Step | undefined;
  /** The run as one status: error if any step failed and nothing is still going, active while anything is pending or active, complete when all settled. */
  status: StepStatus;
  /** Epoch ms span from the first start to the last end, when the steps carry times. */
  durationMs: number | undefined;
};

/** Summarises a list of steps for a rail, a header ("4 of 7"), or a collapsed run ("7 steps · 45s"). */
export function summarizeSteps(steps: readonly Step[]): StepSummary {
  let settled = 0;
  let completed = 0;
  let errored = 0;
  let current: Step | undefined;
  let firstPending: Step | undefined;
  let start = Infinity;
  let end = -Infinity;
  for (const s of steps) {
    if (SETTLED_STEP.has(s.status)) settled++;
    if (s.status === "complete") completed++;
    if (s.status === "error") errored++;
    if (s.status === "active" && !current) current = s;
    if (s.status === "pending" && !firstPending) firstPending = s;
    if (s.startedAt !== undefined) start = Math.min(start, s.startedAt);
    if (s.endedAt !== undefined) end = Math.max(end, s.endedAt);
  }
  const total = steps.length;
  const running = settled < total;
  return {
    total,
    settled,
    completed,
    errored,
    progress: total ? settled / total : 0,
    current: current ?? firstPending,
    status: total === 0 ? "pending" : running ? (current || settled ? "active" : "pending") : errored ? "error" : "complete",
    durationMs: Number.isFinite(start) && Number.isFinite(end) && end >= start ? end - start : undefined,
  };
}

/**
 * Immutable update of one step by id, anywhere in the tree. Stamps `startedAt` when a step
 * becomes active and `endedAt` when it settles, unless the patch sets them.
 *
 *   setSteps((s) => updateStep(s, "search", { status: "complete", detail: "14 sources" }))
 */
export function updateStep(steps: readonly Step[], id: string, patch: Partial<Omit<Step, "id">>, now = Date.now()): Step[] {
  return steps.map((s) => {
    if (s.id === id) {
      const next = { ...s, ...patch };
      if (patch.status === "active" && s.status !== "active" && patch.startedAt === undefined) next.startedAt = now;
      if (patch.status && SETTLED_STEP.has(patch.status) && !SETTLED_STEP.has(s.status) && patch.endedAt === undefined) next.endedAt = now;
      return next;
    }
    return s.steps ? { ...s, steps: updateStep(s.steps, id, patch, now) } : s;
  });
}

/**
 * Settles the active step and activates the next pending one: the usual "next" in a linear run.
 * Returns the steps unchanged when nothing is left to advance.
 */
export function advanceSteps(steps: readonly Step[], outcome: "complete" | "error" | "skipped" = "complete", now = Date.now()): Step[] {
  const active = steps.find((s) => s.status === "active");
  let next: Step[] = [...steps];
  if (active) next = updateStep(next, active.id, { status: outcome }, now);
  const pending = next.find((s) => s.status === "pending");
  if (pending) next = updateStep(next, pending.id, { status: "active" }, now);
  return next;
}

"use client";

import { useEffect, useRef, useState } from "react";

export type UseElapsedOptions = {
  /** Counting while true. When it turns false the value freezes (at `endedAt` if given). Default true. */
  running?: boolean;
  /** When the clock started (epoch ms or Date). Omit to start when `running` first turns true. */
  startedAt?: number | Date;
  /** When it stopped. Use it to show a finished run's exact duration, e.g. from the server. */
  endedAt?: number | Date;
};

const ms = (t: number | Date | undefined) => (t === undefined ? undefined : typeof t === "number" ? t : t.getTime());

/**
 * Whole seconds since a start, ticking exactly on each second boundary of the start time (not
 * of the wall clock), so "1s" appears one second after the start, not up to two. It reads
 * `Date.now()` on every tick rather than counting ticks, so a throttled background tab is
 * still right when it returns. Re-renders once a second while running, and never on the
 * server (it returns 0 until mounted).
 *
 *   const seconds = useElapsed({ running: status === "thinking", startedAt });
 */
export function useElapsed({ running = true, startedAt, endedAt }: UseElapsedOptions = {}): number {
  const start = useRef<number | undefined>(ms(startedAt));
  const frozen = useRef<number | undefined>(undefined);
  const [seconds, setSeconds] = useState(0);

  const startMs = ms(startedAt);
  const endMs = ms(endedAt);

  useEffect(() => {
    if (startMs !== undefined) start.current = startMs;
    const from = () => start.current ?? Date.now();
    if (!running) {
      // Freeze: at the given end, else at the moment it stopped.
      if (start.current === undefined && endMs === undefined) return;
      const stop = endMs ?? frozen.current ?? Date.now();
      frozen.current = stop;
      setSeconds(Math.max(0, Math.floor((stop - from()) / 1000)));
      return;
    }
    // Without a `startedAt`, every new run (running false → true) starts from now.
    if (startMs === undefined && (start.current === undefined || frozen.current !== undefined)) start.current = Date.now();
    frozen.current = undefined;
    let timer = 0;
    const tick = () => {
      const elapsed = Date.now() - from();
      setSeconds(Math.max(0, Math.floor(elapsed / 1000)));
      // Next boundary of the start's own second grid, plus a hair so floor() lands on it.
      timer = window.setTimeout(tick, 1000 - (((elapsed % 1000) + 1000) % 1000) + 4);
    };
    tick();
    return () => clearTimeout(timer);
  }, [running, startMs, endMs]);

  return seconds;
}

/**
 * Seconds as a compact duration: `12s`, `1m 4s`, `1h 2m`. Every digit is a digit, so it rolls
 * cleanly when passed to Number Roll as a `formatter`.
 */
export function formatElapsed(seconds: number): string {
  const s = Math.max(0, Math.floor(seconds));
  if (s < 60) return `${s}s`;
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m ${s % 60}s`;
  return `${Math.floor(m / 60)}h ${m % 60}m`;
}

"use client";

import { useMotionValue, type MotionValue } from "motion/react";
import { useEffect, useRef } from "react";

export type UseTokenRateOptions = {
  /** Tokens per second that reads as full speed (`rate` = 1). Default 60, a fast model's stream. */
  max?: number;
  /**
   * Smoothing time constant in seconds. Streams arrive in bursts; the rate follows the average
   * over roughly this window, so a 40-token chunk reads as a surge, not a spike. Default 0.6.
   */
  smoothing?: number;
  /** Characters per token when `source` is a string. Default 4 (English prose). */
  charsPerToken?: number;
};

export type TokenRate = {
  /** Smoothed tokens per second. */
  tps: MotionValue<number>;
  /** `tps / max`, clamped to 0–1: feed it to anything that should move with the stream. */
  rate: MotionValue<number>;
};

/**
 * How fast a stream is flowing, as motion values, so an orb or a meter can follow it without
 * re-rendering. Pass the streaming text (or a running token count); every change counts the
 * new tokens, and a frame loop turns them into a smoothed tokens-per-second that rises with
 * bursts and decays to 0 when the stream pauses. The loop runs only while the rate is
 * non-zero. If the text shrinks (a new message), it starts over.
 *
 *   const { rate } = useTokenRate(message.text);
 *   <AgentOrb state="speaking" rate={rate} />
 */
export function useTokenRate(source: string | number, { max = 60, smoothing = 0.6, charsPerToken = 4 }: UseTokenRateOptions = {}): TokenRate {
  const tps = useMotionValue(0);
  const rate = useMotionValue(0);
  const last = useRef<number | null>(null);
  const pending = useRef(0);
  const frame = useRef(0);
  const opts = useRef({ max, smoothing });

  useEffect(() => {
    opts.current = { max, smoothing };
  });

  useEffect(() => {
    const count = typeof source === "number" ? source : source.length / charsPerToken;
    const prev = last.current;
    last.current = count;
    if (prev === null || count < prev) return; // first sight, or a reset
    pending.current += count - prev;
    if (frame.current) return;

    let then = performance.now();
    const step = (now: number) => {
      const dt = Math.min(0.1, Math.max(0.001, (now - then) / 1000));
      then = now;
      const observed = pending.current / dt;
      pending.current = 0;
      const { max, smoothing } = opts.current;
      const k = 1 - Math.exp(-dt / Math.max(0.05, smoothing));
      const next = tps.get() + (observed - tps.get()) * k;
      if (next < 0.05) {
        tps.set(0);
        rate.set(0);
        frame.current = 0;
        return;
      }
      tps.set(next);
      rate.set(Math.min(1, next / max));
      frame.current = requestAnimationFrame(step);
    };
    frame.current = requestAnimationFrame(step);
  }, [source, charsPerToken, tps, rate]);

  useEffect(
    () => () => {
      cancelAnimationFrame(frame.current);
      frame.current = 0;
    },
    [],
  );

  return { tps, rate };
}

"use client";

import { useEffect, useState } from "react";

export type UseStatusCarouselOptions = {
  /**
   * A real status. While set it is shown instead of the rotation, at once; when it clears the
   * rotation resumes where it left off. Use it for "Reading stripe.com…" from a tool event.
   */
  status?: string | null;
  /**
   * Milliseconds each line stays. Default: by length, 2.2s plus 45ms a character, capped at
   * 4s, so a long line can be read and a short one does not linger.
   */
  interval?: number | ((line: string) => number);
  /** Stop rotating (keeps the current line). Default false. */
  paused?: boolean;
  /** Start over at the first line when the lines change. Default true. */
  restartOnChange?: boolean;
  /** Cycle back to the first line after the last. Default false: hold on the last line. */
  loop?: boolean;
};

const byLength = (line: string) => Math.min(4000, 2200 + line.length * 45);

/**
 * The line to show from a rotating set of status lines ("Pondering…", "Reading the diff…"),
 * interrupted by a real `status` whenever there is one. By default it holds on the last line
 * instead of looping back, since a status that repeats reads as stuck; set `loop` for
 * ambient lines that may cycle. It does not advance while the tab is hidden. Render the result
 * through Text Swap or Shimmer Text so each change is a swap, not a pop.
 *
 *   const line = useStatusCarousel(["Searching…", "Reading 4 pages…", "Comparing…"], { status });
 *   <ShimmerText>{line}</ShimmerText>
 */
export function useStatusCarousel(lines: readonly string[], { status, interval, paused = false, restartOnChange = true, loop = false }: UseStatusCarouselOptions = {}): string {
  const [index, setIndex] = useState(0);
  // Compared by content, so an inline array literal does not restart the rotation every render.
  const linesKey = lines.join("\u0000");
  const [source, setSource] = useState(linesKey);
  // Adjust state while rendering when the lines change (no effect, no flash of the old line).
  if (source !== linesKey) {
    setSource(linesKey);
    if (restartOnChange) setIndex(0);
  }
  const i = Math.min(index, Math.max(0, lines.length - 1));
  const line = lines[i] ?? "";
  const hold = status ? null : typeof interval === "function" ? interval(line) : (interval ?? byLength(line));
  const atEnd = lines.length < 2 || (!loop && i >= lines.length - 1);

  useEffect(() => {
    if (hold === null || paused || atEnd) return;
    let timer = 0;
    let remaining = hold;
    let since = performance.now();
    const arm = () => {
      since = performance.now();
      timer = window.setTimeout(() => setIndex((n) => (n + 1) % lines.length), remaining);
    };
    const onVisibility = () => {
      if (document.hidden) {
        clearTimeout(timer);
        remaining = Math.max(0, remaining - (performance.now() - since));
      } else arm();
    };
    if (!document.hidden) arm();
    document.addEventListener("visibilitychange", onVisibility);
    return () => {
      clearTimeout(timer);
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [hold, paused, atEnd, i, lines.length]);

  return status || line;
}
